#include <cuda_runtime.h>
#include "../bitpacking-cuda/kernels.cu"
#include "../bitpacking-cuda/utils.cu"
struct Case{size_t n,grid,words,workbytes;int*in,*lo,*hi,*minimum;size_t*num;unsigned char*bits;uint32_t*out;void*work;std::vector<int>host;};
int main(){std::vector<Case>cases;
 for(size_t n:{2,123,3411,83621,872163,1049603}){Case c;c.n=n;c.grid=std::min(size_t(4096),(n+255)/256);c.words=((13*n)/64+1)*2;c.host.resize(n);for(size_t i=0;i<n;i++)c.host[i]=87231+(73*i+19*(i/257))%8192;c.host[0]=87231;c.host[1]=95422;cudaMalloc(&c.in,4*n);cudaMemcpy(c.in,c.host.data(),4*n,cudaMemcpyHostToDevice);cudaMalloc(&c.num,8);cudaMemcpy(c.num,&n,8,cudaMemcpyHostToDevice);cudaMalloc(&c.minimum,4);cudaMalloc(&c.bits,1);cudaMalloc(&c.out,4*c.words);cudaMemset(c.out,0,4*c.words);c.workbytes=requiredWorkspaceSize(n,NVCOMP_TYPE_INT);cudaMalloc(&c.work,c.workbytes);c.hi=(int*)c.work;c.lo=c.hi+getReduceScratchSpaceSize(n);cases.push_back(c);}
 auto launch=[](Case&c){bitPackInternal<int,uint32_t,int>(c.work,c.out,c.in,c.num,c.n,c.minimum,c.bits);};for(auto&c:cases)launch(c);cudaDeviceSynchronize();
 for(int trial=1;trial<=5;trial++){double total=0;bool ok=true;std::vector<uint32_t>got,want;
 for(auto&c:cases){cudaMemset(c.out,0,4*c.words);cudaDeviceSynchronize();auto t=std::chrono::steady_clock::now();for(int i=0;i<1000;i++)launch(c);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/1000;int minimum;unsigned char bits;cudaMemcpy(&minimum,c.minimum,4,cudaMemcpyDeviceToHost);cudaMemcpy(&bits,c.bits,1,cudaMemcpyDeviceToHost);got.push_back(uint32_t(minimum));got.push_back(bits);want.push_back(87231);want.push_back(13);std::vector<int>lo(c.grid,INT_MAX),hi(c.grid,INT_MIN),gl(c.grid),gh(c.grid);std::vector<uint32_t>packed(c.words,0),actual(c.words);for(size_t i=0;i<c.n;i++){size_t g=(i/256)%c.grid;lo[g]=std::min(lo[g],c.host[i]);hi[g]=std::max(hi[g],c.host[i]);uint32_t raw=c.host[i]-87231;size_t bit=i*13,word=bit/32,shift=bit%32;packed[word]|=raw<<shift;if(shift>19)packed[word+1]|=raw>>(32-shift);}cudaMemcpy(gl.data(),c.lo,4*c.grid,cudaMemcpyDeviceToHost);cudaMemcpy(gh.data(),c.hi,4*c.grid,cudaMemcpyDeviceToHost);cudaMemcpy(actual.data(),c.out,4*c.words,cudaMemcpyDeviceToHost);for(auto v:gl)got.push_back(uint32_t(v));for(auto v:gh)got.push_back(uint32_t(v));got.insert(got.end(),actual.begin(),actual.end());for(auto v:lo)want.push_back(uint32_t(v));for(auto v:hi)want.push_back(uint32_t(v));want.insert(want.end(),packed.begin(),packed.end());}
 ok=got==want;std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(got.data(),4,got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"sum_six_sizes_native_full_gpu_config_and_buffered_pack_means\",\"jit_excluded\":true,\"internal_repeats\":1000,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",got.size(),ok?0:1,path.c_str(),got.size());if(!ok)return 6;}
}
